//! Verified fusion-plan application over a Jotnar listing.
//!
//! This is the compiler-side half of the fusion split:
//!
//! * a planner/harness produces a JSON `FusionPlan`;
//! * this module applies only the typed rewrites named in that plan;
//! * the caller re-assembles the result and keeps the provenance sidecar.
//!
//! It never edits the canonical listing and never invents arithmetic. The
//! supported groups are deliberately small; new rules are added here with
//! tests, not generated by an LLM.

use std::collections::HashSet;

use serde_json::{json, Value};

use crate::error::{Error, Result};

pub const PASS_VERSION: &str = "fusion-v1";

/// Apply a fusion plan to listing text.
///
/// The input is unchanged. The returned text has blank lines where a removed
/// op lived; the caller can re-assemble and write it.
pub fn apply(text: &str, plan: &Value) -> Result<(String, Value)> {
    let version = plan
        .get("pass_version")
        .and_then(|v| v.as_str())
        .unwrap_or(PASS_VERSION)
        .to_string();
    let groups = plan
        .get("groups")
        .and_then(|v| v.as_array())
        .ok_or_else(|| Error::asm("fusion plan: missing 'groups' array"))?;
    let mut lines: Vec<String> = text.lines().map(str::to_string).collect();
    let mut records = Vec::new();
    let mut seen_ids = HashSet::new();

    for group in groups {
        let obj = group
            .as_object()
            .ok_or_else(|| Error::asm("fusion plan: group must be an object"))?;
        let id = obj
            .get("id")
            .and_then(|v| v.as_str())
            .ok_or_else(|| Error::asm("fusion plan: group missing id"))?
            .to_string();
        if !seen_ids.insert(id.clone()) {
            return Err(Error::asm(format!("fusion plan: duplicate group id {id:?}")));
        }
        let kind = obj
            .get("kind")
            .and_then(|v| v.as_str())
            .ok_or_else(|| Error::asm(format!("fusion group {id}: missing kind")))?;
        let parity = obj
            .get("parity")
            .and_then(|v| v.as_str())
            .unwrap_or("within-f32");
        let source = match kind {
            "matmul_t" => fuse_matmul_t(&mut lines, obj)?,
            "conv_relu" => fuse_conv_relu(&mut lines, obj)?,
            "bias_matmul" => fuse_bias_matmul(&mut lines, obj)?,
            "head_attn" => fuse_head_attn(&mut lines, obj)?,
            "bias_residual" => fuse_bias_residual(&mut lines, obj)?,
            "bias_gelu" => fuse_bias_gelu(&mut lines, obj)?,
            other => {
                return Err(Error::unimplemented(format!(
                    "fusion group {id}: unsupported kind {other:?}"
                )))
            }
        };
        records.push(json!({
            "id": id,
            "kind": kind,
            "source_streams": source,
            "parity": parity,
        }));
    }

    let joined = lines.join("\n") + "\n";
    let provenance = json!({
        "canonical_hash": fnv1a(text),
        "pass_version": version,
        "fused_hash": fnv1a(&joined),
        "groups": records,
        "note": "Fused listing is a lowering artifact. The canonical listing remains the source of truth."
    });
    Ok((joined, provenance))
}

fn token_count(text: &str, name: &str) -> usize {
    let bytes = text.as_bytes();
    let mut n = 0usize;
    let mut start = 0usize;
    while let Some(pos) = text[start..].find(name) {
        let at = start + pos;
        let before_ok = at == 0 || {
            let c = bytes[at - 1] as char;
            !(c.is_ascii_alphanumeric() || c == '_')
        };
        let after = at + name.len();
        let after_ok = after >= bytes.len() || {
            let c = bytes[after] as char;
            !(c.is_ascii_alphanumeric() || c == '_')
        };
        if before_ok && after_ok {
            n += 1;
        }
        start = after;
    }
    n
}

fn field<'a>(obj: &'a serde_json::Map<String, Value>, key: &str, group: &str) -> Result<&'a str> {
    obj.get(key)
        .and_then(|v| v.as_str())
        .ok_or_else(|| Error::asm(format!("fusion group {group}: missing {key:?}")))
}

fn find_line(lines: &[String], prefix: &str, group: &str) -> Result<usize> {
    let mut hit = None;
    for (i, line) in lines.iter().enumerate() {
        if line.trim().starts_with(prefix) {
            if hit.is_some() {
                return Err(Error::asm(format!(
                    "fusion group {group}: prefix {prefix:?} is not unique"
                )));
            }
            hit = Some(i);
        }
    }
    hit.ok_or_else(|| Error::asm(format!("fusion group {group}: cannot find {prefix:?}")))
}

fn fnv1a(text: &str) -> String {
    let mut h: u64 = 0xcbf29ce484222325;
    for b in text.as_bytes() {
        h ^= *b as u64;
        h = h.wrapping_mul(0x100000001b3);
    }
    format!("{h:016x}")
}

// The real implementations are below; the `obj_fail` indirection above is
// replaced in this file by these concrete signatures.

fn fuse_matmul_t(lines: &mut [String], obj: &serde_json::Map<String, Value>) -> Result<Vec<String>> {
    let group = obj.get("id").and_then(|v| v.as_str()).unwrap_or("?");
    let kt = field(obj, "transpose", group)?;
    let mat = field(obj, "matmul", group)?;
    let ti = find_line(lines, &format!("{kt} = TRANSPOSE("), group)?;
    let mi = find_line(lines, &format!("{mat} = MATMUL("), group)?;
    let targs = lines[ti]
        .trim()
        .strip_prefix(&format!("{kt} = TRANSPOSE("))
        .and_then(|s| s.strip_suffix(')'))
        .ok_or_else(|| Error::asm(format!("fusion group {group}: malformed TRANSPOSE")))?;
    let k = targs.trim();
    let margs = lines[mi]
        .trim()
        .strip_prefix(&format!("{mat} = MATMUL("))
        .and_then(|s| s.strip_suffix(')'))
        .ok_or_else(|| Error::asm(format!("fusion group {group}: malformed MATMUL")))?;
    let parts: Vec<&str> = margs.split(',').map(str::trim).collect();
    if parts.len() != 2 || parts[1] != kt {
        return Err(Error::asm(format!(
            "fusion group {group}: MATMUL does not consume {kt:?} as its right operand"
        )));
    }
    let q = parts[0];
    if token_count(&lines.join("\n"), kt) != 2 {
        return Err(Error::asm(format!(
            "fusion group {group}: {kt:?} has other uses; refusing a lossy rewrite"
        )));
    }
    lines[mi] = format!("{mat} = MATMUL_T({q}, {k})");
    lines[ti].clear();
    Ok(vec![kt.to_string(), mat.to_string()])
}

fn fuse_conv_relu(lines: &mut [String], obj: &serde_json::Map<String, Value>) -> Result<Vec<String>> {
    let group = obj.get("id").and_then(|v| v.as_str()).unwrap_or("?");
    let conv = field(obj, "conv", group)?;
    let relu = field(obj, "relu", group)?;
    let ci = find_line(lines, &format!("{conv} = CONV2D("), group)?;
    let ri = find_line(lines, &format!("{relu} = RELU({conv})"), group)?;
    let args = lines[ci]
        .trim()
        .strip_prefix(&format!("{conv} = CONV2D("))
        .and_then(|s| s.strip_suffix(')'))
        .ok_or_else(|| Error::asm(format!("fusion group {group}: malformed CONV2D")))?;
    if token_count(&lines.join("\n"), conv) != 2 {
        return Err(Error::asm(format!(
            "fusion group {group}: {conv:?} has other uses; refusing a lossy rewrite"
        )));
    }
    lines[ci] = format!("{relu} = CONV2D_RELU({args})");
    lines[ri].clear();
    Ok(vec![conv.to_string(), relu.to_string()])
}

fn fuse_head_attn(lines: &mut [String], obj: &serde_json::Map<String, Value>) -> Result<Vec<String>> {
    let group = obj.get("id").and_then(|v| v.as_str()).unwrap_or("?");
    let q = field(obj, "q", group)?;
    let k = field(obj, "k", group)?;
    let v = field(obj, "v", group)?;
    let out = field(obj, "out", group)?;
    let nh = obj.get("nh").and_then(|x| x.as_u64()).unwrap_or(6) as usize;
    let dh = obj.get("dh").and_then(|x| x.as_u64()).unwrap_or(64) as usize;
    let scale = obj.get("scale").and_then(|x| x.as_f64()).unwrap_or(1.0);

    // Collect the attention subgraph by closure from the three full Q/K/V
    // streams. Stop at `out`; every other internal stream must be used only
    // inside the closure.
    #[derive(Clone)]
    struct L<'a> { idx: usize, out: &'a str, op: &'a str, args: Vec<&'a str> }
    let mut info: Vec<L> = Vec::new();
    for (idx, raw) in lines.iter().enumerate() {
        let line = raw.split('#').next().unwrap_or("").trim();
        if line.is_empty() || line.starts_with("IN ") || line.starts_with("CONFIG") {
            continue;
        }
        let Some((lhs, rhs)) = line.split_once('=') else { continue };
        let lhs = lhs.trim();
        let rhs = rhs.trim();
        let Some((op, rest)) = rhs.split_once('(') else { continue };
        let Some(args) = rest.strip_suffix(')') else { continue };
        let args: Vec<&str> = args.split(',').map(str::trim).collect();
        info.push(L { idx, out: lhs, op: op.trim(), args });
    }
    let by_out = |name: &str| info.iter().find(|l| l.out == name).cloned();
    for name in [q, k, v] {
        let d = by_out(name).ok_or_else(|| Error::asm(format!("fusion group {group}: missing {name:?}")))?;
        if d.op != "MATMUL" {
            return Err(Error::asm(format!("fusion group {group}: {name:?} is not a MATMUL")));
        }
    }
    let mut names: HashSet<&str> = [q, k, v].into_iter().collect();
    let mut expand: HashSet<&str> = names.clone();
    let mut nodes: Vec<L> = Vec::new();
    loop {
        let mut added = false;
        for l in &info {
            if nodes.iter().any(|n| n.idx == l.idx) || [q,k,v].contains(&l.out) {
                continue;
            }
            if !matches!(l.op, "SLICE" | "TRANSPOSE" | "MATMUL" | "SOFTMAX" | "CONCAT") {
                continue;
            }
            if l.out == out {
                if l.args.iter().any(|a| expand.contains(a)) {
                    nodes.push(l.clone());
                    added = true;
                    expand.remove(out);
                }
                continue;
            }
            if l.args.iter().any(|a| expand.contains(a)) {
                nodes.push(l.clone());
                names.insert(l.out);
                expand.insert(l.out);
                added = true;
            }
        }
        if !added { break; }
    }
    if !nodes.iter().any(|n| n.out == out) {
        return Err(Error::asm(format!("fusion group {group}: closure did not reach {out:?}")));
    }
    // Expected local multiset for nh heads: 3*nh slices, nh transposes,
    // 2*nh matmuls, nh softmaxes, nh-1 concats.
    let count = |op: &str| nodes.iter().filter(|n| n.op == op).count();
    if count("SLICE") != 3 * nh
        || count("TRANSPOSE") != nh
        || count("MATMUL") != 2 * nh
        || count("SOFTMAX") != nh
        || count("CONCAT") != nh.saturating_sub(1)
    {
        return Err(Error::asm(format!(
            "fusion group {group}: unexpected attention op counts (slice {} transpose {} matmul {} softmax {} concat {})",
            count("SLICE"), count("TRANSPOSE"), count("MATMUL"), count("SOFTMAX"), count("CONCAT")
        )));
    }
    // Every non-output internal stream must be used only inside the closure;
    // q/k/v are defined outside and may be used only by the closure.
    let all_text = lines.join("\n");
    for name in names.iter().copied().filter(|n| *n != out) {
        let internal = nodes.iter().filter(|n| n.args.contains(&name)).count();
        let total = token_count(&all_text, name);
        let defs = if [q,k,v].contains(&name) { 1 } else { 1 };
        if total != defs + internal {
            return Err(Error::asm(format!(
                "fusion group {group}: {name:?} has external uses; refusing a lossy rewrite"
            )));
        }
    }
    let new_line = format!(
        "{out} = SELF_ATTN({q}, {k}, {v}, {nh}, {dh}, {scale:?})"
    );
    let out_idx = nodes.iter().find(|n| n.out == out).unwrap().idx;
    let node_idx: Vec<usize> = nodes.iter().map(|n| n.idx).collect();
    // Drop all borrows into `lines` before mutating it.
    drop(nodes);
    drop(info);
    drop(names);
    for idx in node_idx {
        if idx != out_idx { lines[idx].clear(); }
    }
    lines[out_idx] = new_line;
    Ok(vec![q.to_string(), k.to_string(), v.to_string(), out.to_string()])
}

fn fuse_bias_residual(lines: &mut [String], obj: &serde_json::Map<String, Value>) -> Result<Vec<String>> {
    let group = obj.get("id").and_then(|v| v.as_str()).unwrap_or("?");
    let mat = field(obj, "matmul_bias", group)?;
    let add = field(obj, "add", group)?;
    let residual = field(obj, "residual", group)?;
    let mi = find_line(lines, &format!("{mat} = MATMUL_BIAS("), group)?;
    let ai = find_line(lines, &format!("{add} = ADD("), group)?;
    let margs = lines[mi]
        .trim()
        .strip_prefix(&format!("{mat} = MATMUL_BIAS("))
        .and_then(|s| s.strip_suffix(')'))
        .ok_or_else(|| Error::asm(format!("fusion group {group}: malformed MATMUL_BIAS")))?;
    let mparts: Vec<&str> = margs.split(',').map(str::trim).collect();
    if mparts.len() != 3 {
        return Err(Error::asm(format!("fusion group {group}: MATMUL_BIAS needs 3 args")));
    }
    let aargs = lines[ai]
        .trim()
        .strip_prefix(&format!("{add} = ADD("))
        .and_then(|s| s.strip_suffix(')'))
        .ok_or_else(|| Error::asm(format!("fusion group {group}: malformed ADD")))?;
    let aparts: Vec<&str> = aargs.split(',').map(str::trim).collect();
    if aparts.len() != 2 || !aparts.contains(&mat) || !aparts.contains(&residual) {
        return Err(Error::asm(format!(
            "fusion group {group}: ADD does not consume {mat:?} and {residual:?}"
        )));
    }
    if token_count(&lines.join("\n"), mat) != 2 {
        return Err(Error::asm(format!(
            "fusion group {group}: {mat:?} has other uses; refusing a lossy rewrite"
        )));
    }
    lines[ai] = format!(
        "{add} = MATMUL_BIAS_RESIDUAL({}, {}, {}, {residual})",
        mparts[0], mparts[1], mparts[2]
    );
    lines[mi].clear();
    Ok(vec![mat.to_string(), add.to_string()])
}

fn fuse_bias_gelu(lines: &mut [String], obj: &serde_json::Map<String, Value>) -> Result<Vec<String>> {
    let group = obj.get("id").and_then(|v| v.as_str()).unwrap_or("?");
    let mat = field(obj, "matmul_bias", group)?;
    let gelu = field(obj, "gelu", group)?;
    let mi = find_line(lines, &format!("{mat} = MATMUL_BIAS("), group)?;
    let gi = find_line(lines, &format!("{gelu} = GELU({mat})"), group)?;
    let margs = lines[mi]
        .trim()
        .strip_prefix(&format!("{mat} = MATMUL_BIAS("))
        .and_then(|s| s.strip_suffix(')'))
        .ok_or_else(|| Error::asm(format!("fusion group {group}: malformed MATMUL_BIAS")))?;
    let mparts: Vec<&str> = margs.split(',').map(str::trim).collect();
    if mparts.len() != 3 {
        return Err(Error::asm(format!("fusion group {group}: MATMUL_BIAS needs 3 args")));
    }
    if token_count(&lines.join("\n"), mat) != 2 {
        return Err(Error::asm(format!(
            "fusion group {group}: {mat:?} has other uses; refusing a lossy rewrite"
        )));
    }
    lines[gi] = format!(
        "{gelu} = MATMUL_BIAS_GELU({}, {}, {})",
        mparts[0], mparts[1], mparts[2]
    );
    lines[mi].clear();
    Ok(vec![mat.to_string(), gelu.to_string()])
}

fn fuse_bias_matmul(lines: &mut Vec<String>, obj: &serde_json::Map<String, Value>) -> Result<Vec<String>> {
    let group = obj.get("id").and_then(|v| v.as_str()).unwrap_or("?");
    let concat = field(obj, "concat", group)?;
    let x = field(obj, "x", group)?;
    let mut mats: Vec<(String, String, String)> = Vec::new();
    if let Some(arr) = obj.get("matmuls").and_then(|v| v.as_array()) {
        for item in arr {
            let o = item.as_object().ok_or_else(|| Error::asm(format!(
                "fusion group {group}: matmuls entries must be objects"
            )))?;
            mats.push((
                field(o, "matmul", group)?.to_string(),
                field(o, "weight", group)?.to_string(),
                field(o, "bias", group)?.to_string(),
            ));
        }
    } else {
        mats.push((
            field(obj, "matmul", group)?.to_string(),
            field(obj, "weight", group)?.to_string(),
            field(obj, "bias", group)?.to_string(),
        ));
    }
    if mats.is_empty() {
        return Err(Error::asm(format!("fusion group {group}: no matmuls")));
    }
    let ci = find_line(lines, &format!("{concat} = CONCAT({x}, ONES, 1)"), group)?;
    if token_count(&lines.join("\n"), concat) != 1 + mats.len() {
        return Err(Error::asm(format!(
            "fusion group {group}: {concat:?} does not have exactly {} consumers",
            mats.len()
        )));
    }
    let mut source = vec![concat.to_string(), x.to_string()];
    for (mat, weight, bias) in &mats {
        let mi = find_line(lines, &format!("{mat} = MATMUL({concat}, {weight})"), group)?;
        lines[mi] = format!("{mat} = MATMUL_BIAS({x}, {weight}, {bias})");
        let decl = format!("IN {bias} AS F:SEQ");
        if !lines.iter().any(|l| l.trim() == decl) {
            lines.push(decl);
        }
        source.push(mat.clone());
        source.push(bias.clone());
    }
    lines[ci].clear();
    Ok(source)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn applies_transpose_and_conv_relu_and_keeps_provenance() {
        let text = "\
IN Q AS F:HW
IN K AS F:HW
IN X AS F:HWC
IN W AS F:CONV
IN B AS F:SEQ
KT = TRANSPOSE(K)
S = MATMUL(Q, KT)
C = CONV2D(X, W, B, 1, 1)
R = RELU(C)
";
        let plan = json!({"pass_version": "fusion-v1", "groups": [
            {"id":"g0","kind":"matmul_t","transpose":"KT","matmul":"S","parity":"within-f32"},
            {"id":"g1","kind":"conv_relu","conv":"C","relu":"R","parity":"exact"}
        ]});
        let (fused, prov) = apply(text, &plan).expect("fusion");
        assert!(fused.contains("S = MATMUL_T(Q, K)"));
        assert!(fused.contains("R = CONV2D_RELU(X, W, B, 1, 1)"));
        assert!(!fused.contains("TRANSPOSE"));
        assert_eq!(prov["groups"].as_array().unwrap().len(), 2);
        assert_eq!(prov["pass_version"], "fusion-v1");
    }

    #[test]
    fn applies_shared_bias_concat() {
        let text = "\
IN X AS F:HW
IN W1 AS F:HW
IN W2 AS F:HW
IN B1 AS F:SEQ
IN B2 AS F:SEQ
H = CONCAT(X, ONES, 1)
A = MATMUL(H, W1)
B = MATMUL(H, W2)
";
        let plan = json!({"groups":[
            {"id":"b0","kind":"bias_matmul","concat":"H","x":"X","matmuls":[
                {"matmul":"A","weight":"W1","bias":"B1"},
                {"matmul":"B","weight":"W2","bias":"B2"}
            ]}
        ]});
        let (fused, prov) = apply(text, &plan).expect("shared bias");
        assert!(fused.contains("A = MATMUL_BIAS(X, W1, B1)"));
        assert!(fused.contains("B = MATMUL_BIAS(X, W2, B2)"));
        assert!(!fused.contains("CONCAT(X, ONES, 1)"));
        assert_eq!(prov["groups"].as_array().unwrap().len(), 1);
    }

    #[test]
    fn applies_head_attn_closure() {
        let text = "\
IN Q0 AS F:HW
IN K0 AS F:HW
IN V0 AS F:HW
QA = MATMUL(Q0, Q0)
KA = MATMUL(K0, K0)
VA = MATMUL(V0, V0)
S0 = SLICE(QA, 1, 0, 64)
K0S = SLICE(KA, 1, 0, 64)
V0S = SLICE(VA, 1, 0, 64)
KT = TRANSPOSE(K0S)
SC = MATMUL(S0, KT)
P = SOFTMAX(SC)
O = MATMUL(P, V0S)
";
        let plan = json!({"groups":[
            {"id":"h0","kind":"head_attn","q":"QA","k":"KA","v":"VA","out":"O","nh":1,"dh":64}
        ]});
        let (fused, prov) = apply(text, &plan).expect("head_attn");
        assert!(fused.contains("O = SELF_ATTN(QA, KA, VA, 1, 64, 1.0)"));
        assert!(!fused.contains("SLICE"));
        assert_eq!(prov["groups"].as_array().unwrap().len(), 1);
    }

    #[test]
    fn applies_bias_residual_and_gelu_epilogues() {
        let text = "\
IN A AS F:HW
IN W AS F:HW
IN B AS F:SEQ
IN X AS F:HW
A1 = MATMUL_BIAS(A, W, B)
X1 = ADD(X, A1)
M1 = MATMUL_BIAS(X1, W, B)
M1G = GELU(M1)
";
        let plan = json!({"groups":[
            {"id":"r0","kind":"bias_residual","matmul_bias":"A1","add":"X1","residual":"X"},
            {"id":"g0","kind":"bias_gelu","matmul_bias":"M1","gelu":"M1G"}
        ]});
        let (fused, prov) = apply(text, &plan).expect("epilogues");
        assert!(fused.contains("X1 = MATMUL_BIAS_RESIDUAL(A, W, B, X)"));
        assert!(fused.contains("M1G = MATMUL_BIAS_GELU(X1, W, B)"));
        assert_eq!(prov["groups"].as_array().unwrap().len(), 2);
    }

    #[test]
    fn refuses_reused_intermediate() {
        let text = "\
IN Q AS F:HW
IN K AS F:HW
KT = TRANSPOSE(K)
S = MATMUL(Q, KT)
T = ADD(KT, KT)
";
        let plan = json!({"groups":[
            {"id":"g0","kind":"matmul_t","transpose":"KT","matmul":"S"}
        ]});
        assert!(apply(text, &plan).is_err());
    }
}
